import React from 'react';
export default function Journey() {
  return (
        <section className="section-wrap journey-section">
          <div className="section-label">04 / MY APPROACH</div><div className="journey-grid"><div><h2>Learn.<br/><span className="muted-heading">Build. Improve.</span></h2><p className="section-lead">My approach to becoming a stronger developer.</p></div><div className="journey-steps"><div className="journey-step"><span>01</span><div><h3>Understand the problem</h3><p>Break requirements into clear, manageable tasks before writing code.</p></div></div><div className="journey-step"><span>02</span><div><h3>Build with care</h3><p>Create responsive interfaces and connect them to reliable backend services.</p></div></div><div className="journey-step"><span>03</span><div><h3>Test and keep learning</h3><p>Debug thoughtfully, improve the experience and keep expanding my skills.</p></div></div></div></div>
        </section>
  );
}
